CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT NOT NULL UNIQUE COLLATE NOCASE, pass_hash TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, ts INTEGER NOT NULL, lang TEXT NOT NULL, ctx TEXT NOT NULL, cat TEXT NOT NULL, title TEXT NOT NULL, sev TEXT, code TEXT NOT NULL, fixed TEXT NOT NULL, evidence TEXT, cause TEXT, ver TEXT, line INTEGER, tests TEXT NOT NULL DEFAULT '[]');
CREATE INDEX IF NOT EXISTS idx_sessions_user_ts ON sessions(user_id, ts DESC);
